def generate(seed):
    r = random.Random(seed)
    n = r.randint(8, 10)
    A = [r.randint(0, 1) for _ in range(n)]
    cl = []
    for k in range(int(n * 3.5)):
        if k == 0:
            vs = [n] + r.sample([v for v in range(1, n + 1) if v != n], 2)
            r.shuffle(vs)
        else:
            vs = r.sample(range(1, n + 1), 3)
        lits = [v if r.random() < .5 else -v for v in vs]
        if not any((l > 0) == (A[abs(l) - 1] == 1) for l in lits):
            i = r.randrange(3)
            lits[i] = -lits[i]
        cl.append(','.join(str(l) for l in lits))
    return ' '.join(cl)

