def solve(clue):
    C = [[int(t) for t in q.split(',')] for q in clue.split()]
    n = max(abs(t) for q in C for t in q)
    P, N = [], []
    for q in C:
        p = g = 0
        for t in q:
            if t > 0:
                p |= 1 << (t - 1)
            else:
                g |= 1 << (-t - 1)
        P.append(p)
        N.append(g)
    for a in range(1 << n):
        if all((a & p) or (~a & g) for p, g in zip(P, N)):
            return ''.join('1' if a >> i & 1 else '0' for i in range(n))
    return ''

